void to_lower(string &s){
    for(int i = 0; i < s.size(); i++)
        s[i] = tolower(s[i]);
}
void to_upper(string &s){
    for(int i = 0; i < s.size(); i++)
        s[i] = toupper(s[i]);
}
// s = "codelab BLOG" -> to_lower(s) -> "codelab blog"

string to_lower(string s){
    for(int i = 0; i < s.size(); i++)
        if(s[i]>='A' && s[i]<='Z') s[i] += 32;
    return s;
}
string to_upper(string s){
    for(int i = 0; i < s.size(); i++)
        if(s[i]>='a' && s[i]<='z') s[i] -= 32;
    return s;
}
